FUNCTION_BLOCK FB
VAR_INPUT
    runRequest      : BOOL;
    pressure        : REAL;
    pressureValid   : BOOL;
    fuelFlow        : REAL;
    steamFlow       : REAL;
    outletCmd       : INT;
    outletFeedback  : INT;
    resetBtn        : BOOL;
END_VAR
VAR_OUTPUT
    tripLatched     : BOOL;
    fuelPermit      : BOOL;
    currentCauseMask : WORD;
    latchedCauseMask : WORD;
    diagnosticActive : BOOL;
END_VAR
VAR
    prevResetBtn    : BOOL := FALSE;
    prevRunRequest  : BOOL := FALSE;
    stickyConsecutive : INT := 0;
END_VAR

VAR_TEMP
    risingReset     : BOOL;
    causeMask       : WORD;
END_VAR

    risingReset := resetBtn AND NOT prevResetBtn;

    IF runRequest THEN
        IF pressureValid THEN
            IF pressure >= 4500.0 THEN
                tripLatched := TRUE;
            END_IF
        ELSE
            tripLatched := TRUE;
        END_IF
    END_IF;

    IF risingReset AND NOT runRequest AND pressureValid AND pressure <= 4200.0 THEN
        tripLatched := FALSE;
    END_IF;

    causeMask := 0;

    IF NOT pressureValid THEN
        causeMask := causeMask OR TO_WORD(1);
    END_IF;

    IF runRequest AND pressureValid AND pressure >= 4500.0 AND outletCmd >= 50 AND outletFeedback <= 10 THEN
        stickyConsecutive := stickyConsecutive + 1;
        IF stickyConsecutive >= 3 THEN
            causeMask := causeMask OR TO_WORD(2);
        END_IF;
    ELSE
        stickyConsecutive := 0;
    END_IF;

    IF fuelFlow >= 4.0 AND steamFlow <= 10.0 THEN
        causeMask := causeMask OR TO_WORD(4);
    END_IF;

    IF runRequest AND pressureValid AND pressure >= 4500.0 AND causeMask = 0 THEN
        causeMask := causeMask OR TO_WORD(8);
    END_IF;

    IF NOT runRequest THEN
        causeMask := 0;
    END_IF;

    currentCauseMask := causeMask;

    IF tripLatched THEN
        latchedCauseMask := latchedCauseMask OR causeMask;
    END_IF;

    IF risingReset THEN
        latchedCauseMask := 0;
    END_IF;

    fuelPermit := runRequest AND NOT tripLatched;

    diagnosticActive := (currentCauseMask <> 0);

    prevResetBtn := resetBtn;
    prevRunRequest := runRequest;
END_FUNCTION_BLOCK
